bookSourceComment:
//YesPlayMusic_简约而不简单
//v1.2
//增加登录js
//支持读取本地自定义歌单
//歌单不再显示付费歌曲
//发现支持获取用户歌单
//支持添加网址获取歌单，格式如下：
// https://music.163.com/#/playlist?id=7705278762
// https://y.music.163.com/m/playlist?id=7705278762
[//自定义歌单_开始
//只支持网易云歌单id
{"name":"洛天依","picUrl":"http://p4.music.126.net/2dJ9Fo7HfkRExyICXG_t3g==/109951167677450486.jpg","id":"7705278762"},
//歌单参数示例
//齐全的参数直观好看，但是在源注释填写太耗地方，建议放到本地txt填写。
{
//必填，书籍名称。
//更改参数后需要重新加入书架。
"name": "歌单示例1",
//可选，作者名称
//无参数默认为"🎶 简单音乐"
"creator":{"nickname":"@Thomas喲"},
//可选，歌单分类
"tags": ["歌单示例","轻松","愉快","悠然"],
//可选，歌单简介
"description": "歌单示例1是简单音乐_书源里面的默认自定义歌单，整个歌单共有 2首歌？由@Thomas喲分享。",
//可选，歌单封面链接
//无参数会启用默认封面
"picUrl": "",
