        eval(fun);
      list=packedarr;

       var piclist = new Array([list.length]);
       for (var i = 0; i < list.length; i++) {
       host = "https://mh.blueseeker.net/";
       var ul = list[i].substr(0,4);
       if(ul=='2017'){
               host='http://omh.jiduo.cc/';
       }
        piclist[i] = host + list[i];
        }
        return piclist;
    }else {
        return null;
    }
}()).map(uri=>'<img src="'+uri+'">').join("\n")

